  getClimateSurveyWorksheet() {
    if (!this.workbook) {
      return null;
    }
    const sheetNames = this.workbook.SheetNames || [];
    const preferredSheet = sheetNames.find((sheetName) => {
      const normalizedName = this.normalizeExcelText(sheetName);
      return ["ENCUESTA", "SURVEY", "PREGUNTAS", "QUESTIONS"].includes(normalizedName);
    });
    const fallbackSheet = sheetNames.find((sheetName) => {
      const normalizedName = this.normalizeExcelText(sheetName);
      return !["INSTRUCCIONES", "INSTRUCTIONS", "README", "LEEME"].includes(normalizedName);
    });
    const selectedSheetName = preferredSheet || fallbackSheet;
    return selectedSheetName ? this.workbook.Sheets[selectedSheetName] : null;
  }
  getClimateExcelAllowedTypesText() {
    const allowedTypes = this.langStoreValue === "en" ? ["SURVEY", "FACTOR", "LIKERT", "OPEN QUESTION", "AI QUESTION", "RANGE", "LIST", "DEMOGRAPHIC LIST"] : ["ENCUESTA", "FACTOR", "LIKERT", "PREGUNTA ABIERTA", "PREGUNTA IA", "RANGO", "LISTA", "LISTA DEMOGRAFICO"];
    return allowedTypes.map((type) => `'${type}'`).join(", ");
  }
  normalizeClimateExcelType(value) {
    const normalizedType = this.normalizeExcelText(value);
    switch (normalizedType) {
      case "ENCUESTA":
      case "SURVEY":
      case "GRAN FACTOR":
      case "MAIN FACTOR":
      case "PRINCIPAL FACTOR":
        return "ENCUESTA";
      case "FACTOR":
        return "FACTOR";
      case "LIKERT":
        return "LIKERT";
      case "PREGUNTA ABIERTA":
      case "OPEN QUESTION":
        return "PREGUNTA ABIERTA";
      case "PREGUNTA IA":
      case "IA QUESTION":
      case "AI QUESTION":
        return "PREGUNTA IA";
      case "RANGO":
      case "RANGE":
        return "RANGO";
      case "LISTA":
      case "LIST":
        return "LISTA";
      case "LISTA DEMOGRAFICO":
      case "DEMOGRAPHIC LIST":
        return "LISTA DEMOGRAFICO";
      default:
        return "";
    }
  }
