  parseFechaManual(fechaTexto) {
    if (!fechaTexto || typeof fechaTexto !== "string") {
      console.warn("Fecha vac\xEDa o no es string:", fechaTexto);
      return null;
    }
    const partes = fechaTexto.split("/");
    if (partes.length !== 3) {
      console.warn("La fecha no tiene 3 partes:", fechaTexto);
      return null;
    }
    const [diaStr, mesStr, anioStr] = partes;
    const dia = parseInt(diaStr, 10);
    const mes = parseInt(mesStr, 10) - 1;
    const anio = parseInt(anioStr, 10);
    const fecha = new Date(anio, mes, dia);
    if (isNaN(fecha.getTime())) {
      console.warn("La fecha es inv\xE1lida:", fechaTexto, fecha);
      return null;
    }
    return fecha.toISOString().split("T")[0];
  }
