  generarUID() {
    const fecha = /* @__PURE__ */ new Date();
    const a\u00F1o = fecha.getFullYear();
    const mes = (fecha.getMonth() + 1).toString().padStart(2, "0");
    const dia = fecha.getDate().toString().padStart(2, "0");
    const hora = fecha.getHours().toString().padStart(2, "0");
    const minuto = fecha.getMinutes().toString().padStart(2, "0");
    const segundo = fecha.getSeconds().toString().padStart(2, "0");
    const uid = `${mes}${dia}${hora}${minuto}${segundo}`;
    return uid;
  }
  getNextQuestionSequence() {
    const names = /* @__PURE__ */ new Set();
    for (const gf of this.granFactores || []) {
      for (const serie of gf?.series || []) {
        for (const field of serie?.fields || []) {
          const name = String(field?.name ?? "").trim();
          if (name) {
            names.add(name);
          }
        }
      }
    }
    for (const item of this.dataSource || []) {
      const name = String(item?.name ?? "").trim();
      if (name) {
        names.add(name);
      }
    }
    let max = 0;
    for (const name of names) {
      const match = name.match(/_(\d+)$/);
      if (!match) {
        continue;
      }
      const value = Number(match[1]);
      if (!Number.isNaN(value) && value > max) {
        max = value;
      }
    }
    return max + 1;
  }
  getCurrentQuestionsCount() {
    return (this.granFactores || []).reduce((granFactorTotal, granFactor) => {
      const factorQuestions = (granFactor?.series || []).reduce((factorTotal, factor) => {
        const questionCount = Array.isArray(factor?.fields) ? factor.fields.length : 0;
        return factorTotal + questionCount;
      }, 0);
      return granFactorTotal + factorQuestions;
    }, 0);
  }
  canAddQuestions(incomingCount = 1) {
    const currentCount = this.getCurrentQuestionsCount();
    if (!this.demoLimitsService.exceedsLimit("maxQuestionsPerClimate", currentCount, incomingCount)) {
      return true;
    }
    const limit = this.demoLimitsService.getLimit("maxQuestionsPerClimate");
    const remaining = this.demoLimitsService.getRemaining("maxQuestionsPerClimate", currentCount);
    const requestedText = incomingCount > 1 ? ` Intentaste agregar ${incomingCount} preguntas.` : "";
    import_sweetalert22.default.fire({
      title: "Limite demo alcanzado",
      text: `Solo se puede ingresar ${limit} preguntas en este clima demo.` + requestedText + ` Actualmente existen ${currentCount} registradas y solo quedan ${remaining} espacio(s) disponibles.`,
      icon: "warning"
    });
    return false;
  }
