  validarRespuestaWhatsapp(response) {
    const payload = response?.data && typeof response.data === "object" ? response.data : response;
    const messagingProduct = (payload?.messaging_product ?? "").toString().toLowerCase();
    const contact = payload?.contacts?.[0] ?? null;
    const message = payload?.messages?.[0] ?? null;
    const status = (message?.message_status ?? "").toString();
    const ok = messagingProduct === "whatsapp" && status.toLowerCase() === "accepted" && Boolean(contact?.wa_id || contact?.input) && Boolean(message?.id);
    if (ok) {
      return { ok: true, status, detalle: "" };
    }
    const errores = [];
    if (messagingProduct !== "whatsapp")
      errores.push("messaging_product inv\xE1lido");
    if (!contact?.wa_id && !contact?.input)
      errores.push("contacto no retornado");
    if (!message?.id)
      errores.push("id de mensaje no retornado");
    if (!status) {
      errores.push("message_status vac\xEDo");
    } else if (status.toLowerCase() !== "accepted") {
      errores.push(`message_status=${status}`);
    }
    return {
      ok: false,
      status,
      detalle: errores.join(", ") || "Respuesta de WhatsApp inv\xE1lida"
    };
  }
